94	// runConfigureOnboarding is a seam for command tests. Bare interactive
95	// `entire configure` is the new end-to-end entry point; flag-based configure
96	// remains the non-interactive settings editor.
97	var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
98		return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
99	}
100	
101	func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
102		cmd.SilenceUsage = true
103		ctx := cmd.Context()
104		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
105	
106		repoRoot, err := paths.WorktreeRoot(ctx)
107		if err != nil {
108			fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
109			return NewSilentError(errors.New("not a git repository"))
110		}
111		owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
112		if err != nil {
113			return err
114		}
115	
116		profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
117		if err != nil {
118			return err
119		}
120	
121		reporter, err := deps.accessClient(ctx)
122		if err != nil {
123			return fmt.Errorf("connect to Entire: %w", err)
124		}
125		access, err := reporter.ReportEnable(ctx, cleanRemote)
126		if err != nil {
127			return fmt.Errorf("check repository access: %w", err)
128		}
129		if !access.Connected {
130			if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, opts.Yes, deps); err != nil {
131				return err
132			}
133		}
134	
135		client, err := deps.coreClient()
136		if err != nil {
137			return fmt.Errorf("connect to Entire control plane: %w", err)
138		}
139		placements, err := resolvePullablePlacements(ctx, client, owner, repo)
140		if err != nil {
141			return renderCoreError(err)
142		}
143		if len(placements) == 0 {
144			placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction, opts.Yes)
145			if err != nil {
146				return err
147			}
148		}
149		if len(placements) == 0 {
150			return errors.New("no usable mirror was selected")
151		}
152	
153		manageRegionsHint := ""
154		if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
155			manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
156				configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
157		}
158		initialChanges, err := configureGitChanges(ctx, repoRoot)
159		if err != nil {
160			return err
161		}
162		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
163		if branchErr != nil {
164			// Best-effort: local-only saves do not need a branch.
165			branch = ""
166		}
167		protected := false
168		protectionKnown := branch == ""
169		if branch != "" {
170			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
171				protected = detected
172				protectionKnown = true
173			}
174		}
175		// Non-interactive onboarding has no confirmation step. If GitHub protection
176		// cannot be checked (common when gh is unavailable in CI), fail closed and
177		// use the review branch rather than pushing directly to the checked-out
178		// branch. Interactive users can still explicitly choose a direct push when
179		// protection is known not to block it.
180		protected = configureEffectiveProtection(protected, protectionKnown, opts.Yes)
181		branchPushSafe := false
182		if branch != "" && len(initialChanges) == 0 {
183			branchPushSafe = configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)
184		}
185		chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
186			ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
187			branch, protected, branchPushSafe, opts.Yes,
188		)
189		if err != nil {
190			return err
191		}
192		if saveChoice == configureSaveCancel {
193			fmt.Fprintln(outW, "Configuration cancelled.")
194			return nil
195		}
196		if saveChoice == "" {
197			fmt.Fprintln(outW, "No configuration changes.")
198			return nil
199		}
200	
201		// Snapshot immediately before applying our changes. The form may have been
202		// open for an arbitrary amount of time, so the pre-form status is not a safe
203		// commit baseline: editor autosaves or another process may have changed files
204		// while the user was choosing options. Anything already dirty now is excluded
205		// from generated and disables automatic commit/push below.
206		beforeApply, err := configureGitChanges(ctx, repoRoot)
207		if err != nil {
208			return err
209		}
210		if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
211			(len(beforeApply) != 0 || !configureBranchHasNoUnpushedCommits(ctx, repoRoot, branch)) {
212			saveChoice = configureSaveLocal
213		}
214	
215		forgeRemote, err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen)
216		if err != nil {
217			return err
218		}
219	
220		if agentsChanged {
221			opts = configureOnboardingEnableOptions(opts)
222			if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
223				return err
224			}
225			// A local enabled:false override must not win over the newly written project
226			// configuration. setEnabledFlag updates the project and synchronizes an
227			// existing local override without replacing its other local-only fields.
228			if err := setEnabledFlag(ctx, true, true); err != nil {
229				return err
230			}
231		}
232	
233		after, err := configureGitChanges(ctx, repoRoot)
234		if err != nil {
235			return err
236		}
237		generated := newConfigureChanges(beforeApply, after)
238		if agentsChanged {
239			fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
240		}
241	
242		if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
243			if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
244				return err
245			}
246		} else if agentsChanged && len(generated) > 0 {
247			fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
248		}
249		fmt.Fprintln(outW, "✓ Configuration complete")
250		fmt.Fprintln(outW)
251		fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
252		fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
253		return nil
254	}
