1153	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1154		remotes, err := listGitRemotes(ctx, repoRoot)
1155		if err != nil {
1156			return "", err
1157		}
1158		current := ""
1159		if remotes[defaultMirrorRemote] {
1160			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1161			if err != nil {
1162				return "", fmt.Errorf("read origin remote URL: %w", err)
1163			}
1164		}
1165	
1166		forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1167		if err != nil {
1168			return "", err
1169		}
1170		preserve := ""
1171		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1172			if forgeRemote == "" {
1173				preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1174				forgeRemote = preserve
1175			}
1176		}
1177		if forgeRemote == "" {
1178			forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1179			forgeURL := configureGitHubForgeURL(ctx, owner, repo)
1180			if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1181				return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1182			}
1183			remotes[forgeRemote] = true
1184			fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1185		}
1186	
1187		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1188		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1189		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1190			return "", err
1191		}
1192		if err := configureRetargetCurrentBranch(ctx, repoRoot, forgeRemote); err != nil {
1193			return "", err
1194		}
1195		// Report the replaced URL and where it remains reachable. The returned
1196		// forgeRemote is deliberately separate from the mirror fetch remote: config
1197		// commits must land on GitHub, never in the one-way Entire mirror.
1198		reportMirrorRemotePlan(outW, errW, plan)
1199		return forgeRemote, nil
1200	}
1201	
1202	var configureGitHubProtocol = func(ctx context.Context) string { //nolint:gochecknoglobals // test seam for the user's gh protocol preference
1203		out, err := exec.CommandContext(ctx, "gh", "config", "get", "git_protocol", "--host", "github.com").Output()
1204		if err != nil {
1205			return "https"
1206		}
1207		protocol := strings.ToLower(strings.TrimSpace(string(out)))
1208		if protocol == configureGitProtocolSSH {
1209			return protocol
1210		}
1211		return "https"
1212	}
1213	
1214	func configureGitHubForgeURL(ctx context.Context, owner, repo string) string {
1215		if configureGitHubProtocol(ctx) == configureGitProtocolSSH {
1216			return fmt.Sprintf("git@github.com:%s/%s.git", owner, repo)
1217		}
1218		return fmt.Sprintf("https://github.com/%s/%s.git", owner, repo)
1219	}
1220	
1221	func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1222		names := make([]string, 0, len(remotes))
1223		for name := range remotes {
1224			if name != exclude {
1225				names = append(names, name)
1226			}
1227		}
1228		sort.SliceStable(names, func(i, j int) bool {
1229			priority := func(name string) int {
1230				switch name {
1231				case mirrorCloneProviderGitHub:
1232					return 0
1233				case defaultMirrorUpstreamRemote:
1234					return 1
1235				default:
1236					return 2
1237				}
1238			}
1239			if priority(names[i]) != priority(names[j]) {
1240				return priority(names[i]) < priority(names[j])
1241			}
1242			return names[i] < names[j]
1243		})
1244		for _, name := range names {
1245			raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1246			if err != nil {
1247				return "", fmt.Errorf("read remote %q URL: %w", name, err)
1248			}
1249			info, err := gitremote.ParseURL(raw)
1250			if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1251				strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1252				return name, nil
1253			}
1254		}
1255		return "", nil
1256	}
1257	
1258	func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
1259		for _, candidate := range candidates {
1260			if !remotes[candidate] {
1261				return candidate
1262			}
1263		}
1264		for i := 2; ; i++ {
1265			candidate := fmt.Sprintf("github-%d", i)
1266			if !remotes[candidate] {
1267				return candidate
1268			}
1269		}
1270	}
1271	
1272	// configureGitChanges returns porcelain status keyed by path. Its values retain
1273	// XY so callers can detect whether anything was already staged before the flow.
1274	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1275		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1276		if err != nil {
1277			return nil, fmt.Errorf("read git status: %w", err)
1278		}
1279		changes := make(map[string]string)
1280		for _, line := range strings.Split(out, "\n") {
1281			if len(line) < 4 {
1282				continue
1283			}
1284			path := strings.TrimSpace(line[3:])
1285			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1286				path = path[arrow+4:]
1287			}
1288			if path != "" {
1289				changes[path] = line[:2]
1290			}
1291		}
1292		return changes, nil
1293	}
1294	
1295	func newConfigureChanges(before, after map[string]string) []string {
1296		paths := make([]string, 0, len(after))
1297		for path := range after {
1298			if _, existed := before[path]; !existed {
1299				paths = append(paths, path)
1300			}
1301		}
1302		sort.Strings(paths)
1303		return paths
1304	}
1305	
1306	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1307		outW := cmd.OutOrStdout()
1308		if len(generated) == 0 {
1309			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1310			return nil
1311		}
1312		if len(before) != 0 {
1313			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1314			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1315			return nil
1316		}
1317	
1318		if branch == "" {
1319			return errors.New("cannot save configuration from a detached HEAD")
1320		}
1321		if protected && choice == configureSaveDirect {
1322			return fmt.Errorf("%s is protected; push to a new branch", branch)
1323		}
1324		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1325			return fmt.Errorf("unknown save choice %q", choice)
1326		}
1327		if forgeRemote == "" {
1328			return errors.New("no GitHub remote available for configuration push")
1329		}
1330	
1331		pushBranch := branch
1332		switchedBranch := false
1333		configurationCommitted := false
1334		if choice == configureSaveNewBranch {
1335			var err error
1336			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, forgeRemote, now)
1337			if err != nil {
1338				return err
1339			}
1340			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1341				return fmt.Errorf("create configuration branch: %w", err)
1342			}
1343			switchedBranch = true
1344			defer func() {
1345				if switchedBranch {
1346					// Best-effort fallback for failures after branch creation. Successful
1347					// paths restore explicitly below so an error can be returned.
1348					if restoreErr := restoreConfigureOriginalBranch(context.WithoutCancel(cmd.Context()), repoRoot, pushBranch, branch, generated, configurationCommitted); restoreErr != nil {
1349						fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not return configuration to original branch %q: %v\n", branch, restoreErr)
1350					}
1351				}
1352			}()
1353		}
1354	
1355		args := []string{"add", "--"}
1356		args = append(args, generated...)
1357		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1358			return fmt.Errorf("stage configuration: %w", err)
1359		}
1360		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1361			return fmt.Errorf("commit configuration: %w", err)
1362		}
1363		configurationCommitted = true
1364		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1365		if err != nil {
1366			return fmt.Errorf("read configuration commit: %w", err)
1367		}
1368		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1369		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1370			return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1371		}
1372		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1373		if choice == configureSaveNewBranch {
1374			if err := restoreConfigureOriginalBranch(cmd.Context(), repoRoot, pushBranch, branch, generated, configurationCommitted); err != nil {
1375				return err
1376			}
1377			switchedBranch = false
1378			fmt.Fprintf(outW, "✓ Returned to %s with configuration applied locally\n", branch)
1379			fmt.Fprintln(outW, "  Open a trail to merge it:")
1380			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1381		}
1382		return nil
1383	}
1384	
1385	func restoreConfigureOriginalBranch(ctx context.Context, repoRoot, sourceBranch, originalBranch string, generated []string, committed bool) error {
1386		if _, err := gitRunner(ctx, repoRoot, "switch", originalBranch); err != nil {
1387			return fmt.Errorf("return to original branch %q: %w", originalBranch, err)
1388		}
1389	
1390		var args []string
1391		if committed {
1392			// Switching to the original branch removes files introduced by the
1393			// configuration commit. Restore only the generated paths from the review
1394			// branch into the worktree, without touching the original branch's index,
1395			// so the repository remains configured while awaiting review.
1396			args = []string{"restore", "--source", sourceBranch, "--worktree", "--"}
1397		} else {
1398			// A failure before commit can carry staged generated files across the
1399			// switch. Unstage those paths while preserving their worktree contents.
1400			args = []string{"reset", "--"}
1401		}
1402		args = append(args, generated...)
1403		if _, err := gitRunner(ctx, repoRoot, args...); err != nil {
1404			return fmt.Errorf("restore configuration on original branch %q: %w", originalBranch, err)
1405		}
1406		return nil
1407	}
1408	
1409	func configureRetargetCurrentBranch(ctx context.Context, repoRoot, forgeRemote string) error {
1410		branch, err := gitRunner(ctx, repoRoot, "branch", "--show-current")
1411		if err != nil {
1412			return fmt.Errorf("read current branch before retargeting upstream: %w", err)
1413		}
1414		if branch == "" {
1415			return nil // detached HEAD; no branch to retarget
1416		}
1417		key := "branch." + branch + ".remote"
1418		trackingRemote, err := gitRunner(ctx, repoRoot, "config", "--get", key)
1419		if err != nil {
1420			var exitErr *exec.ExitError
1421			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1422				return nil // branch has no configured upstream
1423			}
1424			return fmt.Errorf("read tracking remote for branch %q: %w", branch, err)
1425		}
1426		if trackingRemote != defaultMirrorRemote || trackingRemote == forgeRemote {
1427			return nil
1428		}
1429		if _, err := gitRunner(ctx, repoRoot, "config", "--local", key, forgeRemote); err != nil {
1430			return fmt.Errorf("retarget branch %q to GitHub remote %q: %w", branch, forgeRemote, err)
1431		}
1432		return nil
1433	}
1434	
1435	func configureBranchHasNoUnpushedCommits(ctx context.Context, repoRoot, branch string) bool {
1436		if branch == "" {
1437			return false
1438		}
1439		// Compare HEAD with the live branch on the configured tracking remote. A
1440		// remote-tracking ref can remain stale after origin is repointed to the Entire
1441		// mirror, incorrectly making every later configure run look ahead forever.
1442		remote, err := gitRunner(ctx, repoRoot, "config", "--get", "branch."+branch+".remote")
1443		if err != nil || remote == "" || remote == "." {
1444			return false
1445		}
1446		mergeRef, err := gitRunner(ctx, repoRoot, "config", "--get", "branch."+branch+".merge")
1447		if err != nil || !strings.HasPrefix(mergeRef, "refs/heads/") {
1448			return false
1449		}
1450		remoteHead, err := gitRunner(ctx, repoRoot, "ls-remote", "--exit-code", "--heads", remote, mergeRef)
1451		if err != nil {
1452			return false
1453		}
1454		fields := strings.Fields(remoteHead)
1455		if len(fields) < 2 || fields[1] != mergeRef {
1456			return false
1457		}
1458		head, err := gitRunner(ctx, repoRoot, "rev-parse", "HEAD")
1459		return err == nil && strings.TrimSpace(head) == fields[0]
1460	}
1461	
1462	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1463		// GitHub's branch `.protected` flag is true for *any* active ruleset rule.
1464		// A non-blocking rule such as Copilot code review therefore made ordinary
1465		// feature branches look push-protected. Inspect the effective rules instead
1466		// and only require a new branch for rules that can reject a direct update.
1467		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/rules/branches/"+url.PathEscape(branch)).Output()
1468		if err != nil {
1469			return false, fmt.Errorf("check GitHub branch rules: %w", err)
1470		}
1471		return configureRulesBlockDirectPush(out)
1472	}
1473	
1474	func configureRulesBlockDirectPush(raw []byte) (bool, error) {
1475		var rules []struct {
1476			Type string `json:"type"`
1477		}
1478		if err := json.Unmarshal(raw, &rules); err != nil {
1479			return false, fmt.Errorf("parse GitHub branch rules: %w", err)
1480		}
1481		for _, rule := range rules {
1482			switch rule.Type {
1483			case "pull_request", "required_status_checks", "required_deployments", "required_signatures", "merge_queue", "lock_branch", "update", "workflows":
1484				return true, nil
1485			}
1486		}
1487		return false, nil
1488	}
1489	
1490	func availableConfigureBranch(ctx context.Context, repoRoot, forgeRemote string, now func() time.Time) (string, error) {
1491		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1492		for _, candidate := range candidates {
1493			localExists, err := configureLocalBranchExists(ctx, repoRoot, candidate)
1494			if err != nil {
1495				return "", err
1496			}
1497			if localExists {
1498				continue
1499			}
1500			remoteExists, err := configureRemoteBranchExists(ctx, repoRoot, forgeRemote, candidate)
1501			if err != nil {
1502				return "", err
1503			}
1504			if !remoteExists {
1505				return candidate, nil
1506			}
1507		}
1508		return "", errors.New("could not choose an unused configuration branch name")
1509	}
1510	
1511	func configureLocalBranchExists(ctx context.Context, repoRoot, branch string) (bool, error) {
1512		_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+branch)
1513		if err == nil {
1514			return true, nil
1515		}
1516		var exitErr *exec.ExitError
1517		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1518			return false, nil
1519		}
1520		return false, fmt.Errorf("check local configuration branch %q: %w", branch, err)
1521	}
1522	
1523	func configureRemoteBranchExists(ctx context.Context, repoRoot, forgeRemote, branch string) (bool, error) {
1524		// Query the forge directly instead of relying on remote-tracking refs, which
1525		// may be stale or absent in a fresh clone. --exit-code returns 2 when no ref
1526		// matches, and any connectivity/auth failure is treated as an error rather
1527		// than risking reuse of another user's branch.
1528		_, err := gitRunner(ctx, repoRoot, "ls-remote", "--exit-code", "--heads", forgeRemote, "refs/heads/"+branch)
1529		if err == nil {
1530			return true, nil
1531		}
1532		var exitErr *exec.ExitError
1533		if errors.As(err, &exitErr) && exitErr.ExitCode() == 2 {
1534			return false, nil
1535		}
1536		return false, fmt.Errorf("check remote configuration branch %q on %q: %w", branch, forgeRemote, err)
1537	}
